Module Pad_fl2 := BndP_Ns_102.LibSegNs_ad_fl2.
Definition KS_ad_fl2 : list nat := Eval vm_compute in (BG.kept_list 64 Pad_fl2.regs0 Pad_fl2.regs_out0).
Lemma KS_ad_fl2_ok : BG.kept_ok 64 Pad_fl2.regs0 Pad_fl2.regs_out0 KS_ad_fl2 = true. Proof. vm_compute. reflexivity. Qed.
Lemma ad_fl2_conc fx R M (V : nat -> Z) :
  0 <= (V 2%nat) < 2 ^ 64 -> 0 <= (V 36%nat) < 2 ^ 64 -> 0 <= (V 38%nat) < 2 ^ 64 ->
  getr R (reg 2) = Z_to_bv 64 (V 2%nat) -> getr R (reg 10) = Z_to_bv 64 (V 36%nat) ->
  140735332483072 <= (V 36%nat) <= 140737488355232 -> L5.u64_at RSEGS M ((V 36%nat) + 16) (V 38%nat) -> 140735332483072 <= (V 38%nat) <= 140737488355272 -> L5.u64_at RSEGS M (V 38%nat) 785968 ->
  L5.img_clear M 65536 814272 ->
  exists fx' R' M', mem_grows M M'
    /\ (forall a : word, M' a = M a)
    /\ (forall i : Z, 0 <= i < 2 ^ 64 -> M' (Z_to_bv 64 i) = M (Z_to_bv 64 i))
    /\ (msteps RSEGS (st fx R 0x3a658 M) (st fx' R' 0x404e4 M')
        /\ (forall x, In x KS_ad_fl2 -> getr R' (reg x) = getr R (reg x))
        /\ getr R' (reg 6) = Z_to_bv 64 263396
        /\ getr R' (reg 10) = Z_to_bv 64 (V 38%nat)
        /\ getr R' (reg 11) = Z_to_bv 64 785968).
Proof.
  intros pvzI1 pvzI2 pvzI3 G2 G10 pvzI4 K1 pvzI5 K3 K4.
  pose proof (proj1 pvzI1) as HV2l; move HV2l before pvzI1; pose proof (proj2 pvzI1) as HV2r; move HV2r before pvzI1; clear pvzI1. pose proof (proj1 pvzI2) as HV36l; move HV36l before pvzI2; pose proof (proj2 pvzI2) as HV36r; move HV36r before pvzI2; clear pvzI2. pose proof (proj1 pvzI3) as HV38l; move HV38l before pvzI3; pose proof (proj2 pvzI3) as HV38r; move HV38r before pvzI3; clear pvzI3. pose proof (proj1 pvzI4) as K0l; move K0l before pvzI4; pose proof (proj2 pvzI4) as K0r; move K0r before pvzI4; clear pvzI4. pose proof (proj1 pvzI5) as K2l; move K2l before pvzI5; pose proof (proj2 pvzI5) as K2r; move K2r before pvzI5; clear pvzI5.
  set (vz_2 := V 2%nat) in *. set (vz_36 := V 36%nat) in *. set (vz_38 := V 38%nat) in *.
  set (E := Env (fun j : nat => match j with 2%nat => Z_to_bv 64 vz_2 | 36%nat => Z_to_bv 64 vz_36 | 38%nat => Z_to_bv 64 vz_38 | _ => getr R (reg j) end) (fun _ => [])).
  set (VzN := (fun j : nat => match j with 2%nat => vz_2 | 36%nat => vz_36 | 38%nat => vz_38 | _ => bv_unsigned (getr R (reg j)) end)).
  assert (ZA : forall j, bv_unsigned (ev E j) = VzN j).
  { unfold VzN. BigLinkZA.za_tac0 39%nat. }
  assert (HR: regs_ok E Pad_fl2.regs0 R). { apply BG.regs_ok_of_slots. reflexivity. cbn [BG.slots tl Pad_fl2.regs0 nth]. apc_norm. repeat split; slotP ZA. }
  assert (HK: know_ok RSEGS E M Pad_fl2.kn0).
  { unfold know_ok, Pad_fl2.kn0.
    apply Forall_cons. { eapply L5K.kentry_KRange; [evalEk ZA ltac:(clear - HV36l HV36r K0l K0r) | exact (conj K0l K0r)]. }
    apply Forall_cons. { eapply L5K.kentry_KWord8; [evalEk ZA ltac:(clear - HV36l HV36r K0l K0r) | evalEk ZA ltac:(clear - HV38l HV38r K2l K2r) | clear - HV36l HV36r K0l K0r; lia | clear - HV36l HV36r K0l K0r; lia | exactA K1]. }
    apply Forall_cons. { eapply L5K.kentry_KRange; [evalEk ZA ltac:(clear - HV38l HV38r K2l K2r) | exact (conj K2l K2r)]. }
    apply Forall_cons. { eapply L5K.kentry_KWord8; [evalEk ZA ltac:(clear - HV38l HV38r K2l K2r) | evalEk ZA ltac:(clear) | clear - HV38l HV38r K2l K2r; lia | clear - HV38l HV38r K2l K2r; lia | exactA K3]. }
    apply Forall_cons. { eapply L5K.kentry_KImg; [clear; lia | clear; lia | exact K4]. }
    apply Forall_nil. }
  pvz_hg ltac:(idtac; destruct (Pad_fl2.seg_sound_ax fx E R M HR HK ltac:(constructor)) as (fx' & E' & R' & M' & kk & ps & Hnth & Hag & Hms & Hregs & Hx0 & Hrok & Hfr & Hcells & Hgr)).
  change Pad_fl2.NX0 with 64%nat in Hag.
  exists fx', R', M'. pvz_linconj. split. exact Hgr.
  assert (FRW: forall a : word, M' a = M a).
  { intros a. apply Hfr. unfold Pad_fl2.F0.
    apply L5K.outside_nil_e. }
  split. exact FRW.
  split. { intros i Hi. apply FRW; rewrite ?BG.unsigned_lit by exact Hi; assumption. }
  apply L5K.nth_error_single in Hnth. subst ps.
  change (SR.ps_pc Pad_fl2.ps0) with 0x404e4 in Hms. change (SR.ps_regs Pad_fl2.ps0) with (map (fun i => (i, nth i Pad_fl2.regs_out0 (ELit 0))) (seq 1 31)) in Hregs.
  change (SR.ps_cells Pad_fl2.ps0) with Pad_fl2.cells0 in Hcells.
