Definition dinv (R : bvmap 5 word) (M : word -> option byte) (model : Model) (OWN : list (Z * Z)) : Prop :=
  getr R (PMK.reg 2) = Z_to_bv 64 (sp - 16) /\ getr R (PMK.reg 8) = Z_to_bv 64 op /\ (forall k, In k PQH.CSK -> getr R (PMK.reg k) = getr R0 (PMK.reg k))
