(* [comment removed for export] *)
Lemma DEL (OPD : PMS.opdel_spec L HI) fx R M model B n OWN (r' : Z) :
  dinv R M model ((B, n) :: OWN) \/
  (exists R1, dinv R1 M model ((B, n) :: OWN) /\ (forall k, In k PQH.CSK -> getr R (PMK.reg k) = getr R1 (PMK.reg k))
