Lemma PIECE_mem R M model OWN M1 (P : Z -> Prop) :
  dinv R M model OWN -> mem_grows M M1 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ P a -> M1 (Z_to_bv 64 a) = M (Z_to_bv 64 a)) -> (forall a, P a -> WD a) ->
  L5.u64_at RSEGS M1 (sp - 8) (bv_unsigned (getr R0 (PMK.reg 1))) /\ L5.u64_at RSEGS M1 (sp - 16) (bv_unsigned (getr R0 (PMK.reg 8)))
  /\ L5C.stk (hl_sptop L) M1 sp SCRD /\ (forall a, sp <= a < 2 ^ 64 -> ~ WD a -> M1 (Z_to_bv 64 a) = M0 (Z_to_bv 64 a))
  /\ PMK.ek L LBX sp SCRD [(op, 504)] M0 M1 /\ PMK.dk L LBX sp SCRD M0 M1 /\ PMST.base_ok RSEGS AD M1
  /\ (forall a, PMK.cwr L (OWN ++ LBX) a \/ ~ P a).
