(* [comment removed for export] *)
Lemma dinv_regs R R' M model OWN : dinv R M model OWN ->
  (forall k, In k PQH.CSK -> getr R' (PMK.reg k) = getr R (PMK.reg k)) -> getr R' (PMK.reg 2) = getr R (PMK.reg 2) -> getr R' (PMK.reg 8) = getr R (PMK.reg 8) ->
