Lemma dinv_mem R M M1 model OWN (P : Z -> Prop) : dinv R M model OWN -> mem_grows M M1 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ P a -> M1 (Z_to_bv 64 a) = M (Z_to_bv 64 a)) -> (forall a, P a -> WD a) ->
