(* [comment removed for export] *)
Lemma dpiece R M model OWN (fx fx1 : FPState) (pc : Z) R1 (pc1 : Z) M1 (P : Z -> Prop) :
  dinv R M model OWN -> msteps RSEGS (@mkst fx R (Z_to_bv 64 pc) M (seg_rom RSEGS)) (@mkst fx1 R1 (Z_to_bv 64 pc1) M1 (seg_rom RSEGS)) -> mem_grows M M1 ->
  (forall a, 0 <= a < 2 ^ 64 -> ~ P a -> M1 (Z_to_bv 64 a) = M (Z_to_bv 64 a)) -> (forall a, P a -> WD a) -> (forall a, {P a} + {~ P a}) ->
  (hi_heap HI (OWN ++ LBX) cr M1 (m_vmmaps model) -> srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx1 R1 pc1 M1 model) K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R pc M model) K.
Proof.
