Lemma D2 (OPD : PMS.opdel_spec L HI) fx R M model :
  dinv R M model (PQM.mparser_own s ++ PM.vs_own (PQM.a_key st) ++ PM.vs_own (PQM.a_kb st)) ->
  (forall (fx' : FPState) R' M' model', dinv R' M' model' (PQM.mparser_own s ++ PM.vs_own (PQM.a_key st)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' 0x3957c M' model') K) ->
  srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx R 0x39560 M model) K.
