(* [comment removed for export] *)
Lemma D6 (OPD : PMS.opdel_spec L HI) fx R M model :
  dinv R M model (PM.src_own (PQM.p_src s) ++ PM.vs_own (PQM.p_tb s)) ->
  (forall (fx' : FPState) R' M' model', dinv R' M' model' (PM.src_own (PQM.p_src s)) ->
      srealizes RSEGS SCFG (@PMSP.cfg RSEGS fx' R' 0x395f0 M' model') K) ->
