Lemma D7 (SDT : PMS.src_dtor_spec L HI) fx R M model :
  dinv R M model (PM.src_own (PQM.p_src s)) ->
  (forall (fx' : FPState) R' M' model',
      regs_preserved R0 R' -> L5C.hpres L LBX sp SCRD [(op, 504)] M0 M' -> model_but_vm model0 model' -> hi_heap HI LBX cr M' (m_vmmaps model') ->
