Lemma KS_evA2_ok : BG.kept_ok 60 PevA2.regs0 PevA2.regs_out0 KS_evA2 = true. Proof. vm_compute. reflexivity. Qed.
Lemma evA2_conc fx R M (V : nat -> Z) :
