(* [comment removed for export] *)
Module Wu64.
Section WithHeap.
Context {SCFG_P : ScfgP}. Context {bmK : BMode}.   (* [comment removed for export] *)
Variable L : heap_layout.
Variable HI : heap_iface.
Variable P : NESK.sink_policy.
Hypothesis LY : PMS.layout L.
Hypothesis HIok : heap_iface_ok L SCFG HI.
Hypothesis PO : NESK.sink_policy_ok P.
Hypothesis HBS : NESK.sp_hb P NESK.SMZ.
Let KL := PMKS.klayout_S L LY.
Hypothesis PB : NESK.push_back_spec RSEGS CAD EE L HI PMSP.T3 PMSP.T4 P.
Section Call.
Hypothesis SPM : NESK.sp_mode P.
Variables (fx : FPState) (R : bvmap 5 word) (M : word -> option byte) (model : Model) (K : TSet)
          (LBX : list (Z * Z)) (cr : credit) (rr o sp r : Z) (k : NESK.sink).
Hypothesis HH : hi_heap HI (NESK.sink_own k ++ LBX) cr M (m_vmmaps model).
Hypothesis MOK : PMSP.model_ok model.
Hypothesis K0 : K [].
Hypothesis ENT : PMSP.entry CAD L R M sp r 2.
Hypothesis A11 : getr R 11%bv = Z_to_bv 64 rr.
Hypothesis RRO : L5.u64_at RSEGS M rr o.
Hypothesis ALrr : rr mod 8 = 0.
Hypothesis RRlo : sp <= rr.
Hypothesis RRhi : rr + 8 <= hl_sptop L.
Hypothesis RRdj : o + 24 <= rr \/ rr + 8 <= o.
Hypothesis SKA : NESK.sink_at RSEGS L PMSP.T3 PMSP.T4 P M o k.
Hypothesis Olo : sp <= o.
Hypothesis Ohi : o + 24 <= hl_sptop L.
Hypothesis ALo : o mod 8 = 0.
Hypothesis ZKB : NESK.sk_z k + 8 <= NESK.SMZ.
Hypothesis CRED : PMSP.credit_le (NESK.sink_pot P (NESK.sk_c k)) cr.
Hypothesis KONT : forall (fx' : FPState) (R' : bvmap 5 word) (M' : word -> option byte) (model' : Model) (k' : NESK.sink) (cr' : credit),
        regs_preserved R R' ->
        NESK.sink_at RSEGS L PMSP.T3 PMSP.T4 P M' o k' -> NESK.sk_z k' = NESK.sk_z k + 8 ->
        L5C.hpres L LBX sp (PMSP.pm_scr 2) [(o, 24)] M M' ->
        PMSP.credit_keep cr cr' (NESK.sink_pot P (NESK.sk_c k)) (NESK.sink_pot P (NESK.sk_c k')) ->
        model_but_vm model model' -> hi_heap HI (NESK.sink_own k' ++ LBX) cr' M' (m_vmmaps model') ->
        srealizes RSEGS SCFG (PMSP.cfg RSEGS R' r M' model') K.
Let Ws : list L5.range := [(o, 24)].
Definition csl (Ri : bvmap 5 word) : Prop := forall j, In j CSL -> getr Ri (PMK.reg j) = getr R (PMK.reg j).

Definition facts : Prop :=
  L5.ra_ok r /\ getr R (PMK.reg 1) = Z_to_bv 64 r /\ getr R (PMK.reg 2) = Z_to_bv 64 sp
  /\ sp mod 16 = 0 /\ hl_sptop L - 2 ^ 23 + 16384 <= sp /\ sp <= hl_sptop L /\ (0x7fff80000000 <= hl_sptop L <= 2 ^ 47)
  /\ getr R (PMK.reg 3) = Z_to_bv 64 (pa_gp CAD) /\ getr R (PMK.reg 4) = Z_to_bv 64 (pa_tp CAD)
  /\ hl_img_lo L = 0x10000 /\ hl_img_hi L = 0xfa000.
