Let cells : list (Z * Z) := [(sp - 8, bv_unsigned (getr R (PMK.reg 1))); (sp - 16, bv_unsigned (getr R (PMK.reg 8)))].
Let CINV := (NECK.cinv L HI P M model LBX cr sp ov osk en k 20480 cells).
